# Annotation helpers
# ---------------------------------------------------------------------------

_EPS = 1e-12


def _clone_annotation(annotation: Annotation) -> Annotation:
    """
    Never mutate the input annotation in place.
    """
    return deepcopy(annotation)


def _clamp(value: float, low: float = 0.0, high: float = 1.0) -> float:
    return max(low, min(high, value))


def _coerce_fill(image: Image.Image, fill):
    """
    Coerce fill values so they work for RGB, RGBA, L, etc.
    """
    bands = image.getbands()
    n_bands = len(bands)

    if isinstance(fill, int):
        if n_bands == 1:
            return fill
        if "A" in bands:
            return tuple([fill] * (n_bands - 1) + [255])
        return tuple([fill] * n_bands)

    if isinstance(fill, tuple):
        if n_bands == 1:
            return int(fill[0])

        if len(fill) == n_bands:
            return fill

        if len(fill) > n_bands:
            return fill[:n_bands]

        missing = n_bands - len(fill)
        if "A" in bands:
            return tuple(fill) + tuple([255] * missing)

        return tuple(fill) + tuple([fill[-1]] * missing)

    return fill


def _bbox_to_xyxy(bbox) -> tuple[float, float, float, float]:
    """
    Convert normalized cx, cy, w, h bbox to normalized x1, y1, x2, y2.
    Coordinates are allowed to be outside [0, 1] after augmentation.
    """
    x1 = bbox.cx - bbox.w / 2.0
    y1 = bbox.cy - bbox.h / 2.0
    x2 = bbox.cx + bbox.w / 2.0
    y2 = bbox.cy + bbox.h / 2.0
    return x1, y1, x2, y2


def _xyxy_to_cxcywh(
    x1: float,
    y1: float,
    x2: float,
    y2: float,
) -> tuple[float, float, float, float]:
    return (
        (x1 + x2) / 2.0,
        (y1 + y2) / 2.0,
        max(0.0, x2 - x1),
        max(0.0, y2 - y1),
    )


def _set_bbox_from_xyxy(bbox, xyxy: tuple[float, float, float, float]) -> None:
    cx, cy, w, h = _xyxy_to_cxcywh(*xyxy)
    bbox.cx = float(cx)
    bbox.cy = float(cy)
    bbox.w = float(w)
    bbox.h = float(h)


def _set_bbox_values(
    bbox,
    cx: float,
    cy: float,
    w: float,
    h: float,
) -> None:
    bbox.cx = float(cx)
    bbox.cy = float(cy)
    bbox.w = float(w)
    bbox.h = float(h)


def _clip_xyxy_to_unit_square(
    x1: float,
    y1: float,
    x2: float,
    y2: float,
) -> tuple[float, float, float, float] | None:
    """
    Clip a bbox to the image.

    Returns None if the bbox has no visible area at all.
    """
    if x1 > x2:
        x1, x2 = x2, x1
    if y1 > y2:
        y1, y2 = y2, y1

    clipped_x1 = max(0.0, x1)
    clipped_y1 = max(0.0, y1)
    clipped_x2 = min(1.0, x2)
    clipped_y2 = min(1.0, y2)

    if clipped_x2 <= clipped_x1 or clipped_y2 <= clipped_y1:
        return None

    return clipped_x1, clipped_y1, clipped_x2, clipped_y2


def _project_ray_to_image_border(
    start_x: float,
    start_y: float,
    target_x: float,
    target_y: float,
) -> tuple[float, float]:
    """
    Project from a visible button center toward an out-of-frame fastener center.

    The returned point is on the image border and represents the direction of
    the missing fastener. This is used with w = h = 0 for the fastener bbox.
    """
    start_x = _clamp(start_x)
    start_y = _clamp(start_y)

    dx = target_x - start_x
    dy = target_y - start_y

    if abs(dx) < _EPS and abs(dy) < _EPS:
        return start_x, start_y

    candidates: list[tuple[float, float, float]] = []

    if abs(dx) >= _EPS:
        for border_x in (0.0, 1.0):
            t = (border_x - start_x) / dx
            if t >= -_EPS:
                y = start_y + t * dy
                if -_EPS <= y <= 1.0 + _EPS:
                    candidates.append((max(0.0, t), border_x, _clamp(y)))

    if abs(dy) >= _EPS:
        for border_y in (0.0, 1.0):
            t = (border_y - start_y) / dy
            if t >= -_EPS:
                x = start_x + t * dx
                if -_EPS <= x <= 1.0 + _EPS:
                    candidates.append((max(0.0, t), _clamp(x), border_y))

    if candidates:
        _, x, y = min(candidates, key=lambda item: item[0])
        return x, y

    return _clamp(target_x), _clamp(target_y)


def _transform_annotation_boxes(
    annotation: Annotation,
    bbox_transform: Callable[[object], tuple[float, float, float, float]],
) -> Annotation:
    """
    Apply a bbox transform to every pair in an Annotation.

    Rules implemented here:

    1. Labels are deep-copied first; the input Annotation is never modified.
    2. If the transformed button bbox has no visible area in the image, remove
       the entire pair, including the corresponding fastener.
    3. If the button remains visible but the fastener has no visible area, keep
       the pair, but place the fastener center on the image border in the
       direction of the transformed fastener, with w = h = 0.
    4. If a bbox is partially visible, clip it to the image.
    5. The existing `visible` field is not used to make decisions. It is only
       updated for consistency after the geometric transform.
    """
    new_annotation = _clone_annotation(annotation)
    new_pairs = []

    for pair in new_annotation.cloth.pairs:
        button_xyxy = bbox_transform(pair.button.bbox)
        fastener_xyxy = bbox_transform(pair.fastener.bbox)

        clipped_button = _clip_xyxy_to_unit_square(*button_xyxy)

        if clipped_button is None:
            # Button has gone fully out of the image.
            # The fastener for this pair is removed with the button.
            continue

        _set_bbox_from_xyxy(pair.button.bbox, clipped_button)
        pair.button.visible = True

        clipped_fastener = _clip_xyxy_to_unit_square(*fastener_xyxy)

        if clipped_fastener is None:
            # Fastener is fully out of frame, but the button is still visible.
            # Keep directional information by projecting the fastener center to
            # the image border and using a null bbox size.
            button_cx = pair.button.bbox.cx
            button_cy = pair.button.bbox.cy
            fastener_cx, fastener_cy, _, _ = _xyxy_to_cxcywh(*fastener_xyxy)

            border_x, border_y = _project_ray_to_image_border(
                button_cx,
                button_cy,
                fastener_cx,
                fastener_cy,
            )

            _set_bbox_values(
                pair.fastener.bbox,
                cx=border_x,
                cy=border_y,
                w=0.0,
                h=0.0,
            )
            pair.fastener.visible = False
        else:
            _set_bbox_from_xyxy(pair.fastener.bbox, clipped_fastener)
            pair.fastener.visible = True

        new_pairs.append(pair)

    new_annotation.cloth.pairs = new_pairs
    return new_annotation


def _annotation_reference_points(annotation: Annotation) -> list[tuple[float, float]]:
    """
    Return normalized center points for buttons and fasteners.

    Fasteners with w = h = 0 are intentionally included because they can encode
    an out-of-frame direction.
    """
    points = []

    for pair in annotation.cloth.pairs:
        points.append((pair.button.bbox.cx, pair.button.bbox.cy))
        points.append((pair.fastener.bbox.cx, pair.fastener.bbox.cy))

    return points


def _rect_contains_point(
    point: tuple[float, float],
    rect: tuple[float, float, float, float],
) -> bool:
    px, py = point
    x1, y1, x2, y2 = rect

    if x1 > x2:
        x1, x2 = x2, x1
    if y1 > y2:
        y1, y2 = y2, y1

    return x1 <= px <= x2 and y1 <= py <= y2


