class Transform(ABC):
    def __init__(self):
        self.current_epoch = 0

    def set_epoch(self, epoch: int):
        self.current_epoch = max(0, int(epoch))

    @abstractmethod
    def __call__(
        self,
        image: Image.Image,
        labels: Annotation,
    ) -> tuple[Image.Image, Annotation]:
        raise NotImplementedError


class ComposeWithLabels(Transform):
    def __init__(self, transformations):
        super().__init__()
        self.transformations = list(transformations)

    def set_epoch(self, epoch: int):
        super().set_epoch(epoch)

        for transformation in self.transformations:
            if hasattr(transformation, "set_epoch"):
                transformation.set_epoch(epoch)

    def __call__(
        self,
        image: Image.Image,
        labels: Annotation,
    ) -> tuple[Image.Image, Annotation]:
        for transformation in self.transformations:
            image, labels = transformation(image, labels)
        return image, labels


class ComposeWrapper(Transform):
    """
    Wrap an image-only transform so it can be used in a label-aware pipeline.
    """
    def __init__(self, transformation):
        super().__init__()
        self.transformation = transformation

    def __call__(
        self,
        image: Image.Image,
        labels: Annotation,
    ) -> tuple[Image.Image, Annotation]:
        image = self.transformation(image)
        return image, _clone_annotation(labels)


