class RandomSafeErasing(Transform):
    def __init__(
        self,
        p: float = 0.2,
        min_width: float = 0.02,
        max_width: float = 0.2,
        min_height: float = 0.02,
        max_height: float = 0.2,
        safety_radius: float = 0.04,
        max_trials: int = 20,
        fill=(0, 0, 0),
    ):
        super().__init__()
        self.p = p
        self.min_width = min_width
        self.max_width = max_width
        self.min_height = min_height
        self.max_height = max_height
        self.safety_radius = safety_radius
        self.max_trials = max_trials
        self.fill = fill

    def _is_safe_rectangle(
        self,
        points_to_avoid: list[tuple[float, float]],
        x0: float,
        y0: float,
        x1: float,
        y1: float,
        W: int,
        H: int,
    ) -> bool:
        radius_x = self.safety_radius * W
        radius_y = self.safety_radius * H

        for normalized_x, normalized_y in points_to_avoid:
            px = normalized_x * W
            py = normalized_y * H

            safe_x0 = px - radius_x
            safe_y0 = py - radius_y
            safe_x1 = px + radius_x
            safe_y1 = py + radius_y

            overlaps = not (
                x1 < safe_x0
                or x0 > safe_x1
                or y1 < safe_y0
                or y0 > safe_y1
            )

            if overlaps:
                return False

        return True

    def __call__(
        self,
        image: Image.Image,
        labels: Annotation,
    ) -> tuple[Image.Image, Annotation]:
        new_labels = _clone_annotation(labels)

        if random.random() > self.p:
            return image, new_labels

        W, H = image.size
        out = image.copy()
        draw = ImageDraw.Draw(out)

        points_to_avoid = _annotation_reference_points(new_labels)

        n_rectangles = random.randrange(1, 3)
        n_done = 0

        for _ in range(self.max_trials):
            if n_done >= n_rectangles:
                break

            erase_w = max(1, int(random.uniform(self.min_width, self.max_width) * W))
            erase_h = max(1, int(random.uniform(self.min_height, self.max_height) * H))

            erase_w = min(erase_w, W)
            erase_h = min(erase_h, H)

            x0 = random.randint(0, W - erase_w)
            y0 = random.randint(0, H - erase_h)
            x1 = x0 + erase_w
            y1 = y0 + erase_h

            if not self._is_safe_rectangle(
                points_to_avoid,
                x0,
                y0,
                x1,
                y1,
                W,
                H,
            ):
                continue

            draw.rectangle(
                [x0, y0, x1, y1],
                fill=_coerce_fill(image, self.fill),
            )
            n_done += 1

        return out, new_labels


class RandomButtonErasing(Transform):
    """
    Erases a rectangle around a randomly selected button.

    Any pair whose button center is inside the erased rectangle is removed.
    This follows the requested rule: once the button is not visible, the
    corresponding fastener is removed as well.
    """
    def __init__(
        self,
        p: float = 0.25,
        min_size: float = 0.05,
        max_size: float = 0.2,
    ):
        super().__init__()
        self.p = p
        self.min_size = min_size
        self.max_size = max_size

    def __call__(
        self,
        image: Image.Image,
        labels: Annotation,
    ) -> tuple[Image.Image, Annotation]:
        new_labels = _clone_annotation(labels)

        if random.random() > self.p or len(new_labels.cloth.pairs) == 0:
            return image, new_labels

        W, H = image.size

        selected_pair = random.choice(new_labels.cloth.pairs)
        button = selected_pair.button.bbox

        center_x = button.cx * W
        center_y = button.cy * H

        erase_w = random.uniform(self.min_size, self.max_size) * W
        erase_h = random.uniform(self.min_size, self.max_size) * H

        rect = (
            center_x - erase_w / 2.0,
            center_y - erase_h / 2.0,
            center_x + erase_w / 2.0,
            center_y + erase_h / 2.0,
        )

        fill_value = random.randint(0, 160)
        fill = _coerce_fill(image, fill_value)

        out = image.copy()
        draw = ImageDraw.Draw(out)
        draw.rectangle(rect, fill=fill)

        kept_pairs = []

        for pair in new_labels.cloth.pairs:
            point = (
                pair.button.bbox.cx * W,
                pair.button.bbox.cy * H,
            )

            if _rect_contains_point(point, rect):
                continue

            kept_pairs.append(pair)

        new_labels.cloth.pairs = kept_pairs
        return out, new_labels


class RandomProgressiveFoveatedBlur(Transform):
    """
    Blur is strongest far from the buttons/fasteners and weakest near them.

    Progressive behavior:
    - call set_epoch(epoch) from the training loop
    - the maximum blur radius decreases over time
    """
    def __init__(
        self,
        p: float = 0.3,
        current_epoch: int = 0,
        initial_max_blur_radius: float = 15.0,
        final_max_blur_radius: float = 0.0,
        blur_levels: int = 6,
        keep_radius: float = 0.015,
        fade_radius: float = 0.12,
        center_jitter: float = 0.0,
        total_decay_epochs: int = 20,
        decay_every: int = 1,
        schedule: str = "cosine",
        blur_mode: str = "box",
        smoothstep: bool = True,
    ):
        super().__init__()
        self.p = p
        self.initial_max_blur_radius = initial_max_blur_radius
        self.final_max_blur_radius = final_max_blur_radius
        self.blur_levels = max(2, int(blur_levels))
        self.keep_radius = keep_radius
        self.fade_radius = fade_radius
        self.center_jitter = center_jitter
        self.total_decay_epochs = max(1, int(total_decay_epochs))
        self.decay_every = max(1, int(decay_every))
        self.schedule = schedule
        self.blur_mode = blur_mode
        self.smoothstep = smoothstep
        self.current_epoch = max(0, int(current_epoch))

        if self.fade_radius < self.keep_radius:
            raise ValueError("fade_radius must be >= keep_radius")

    def _get_progress(self) -> float:
        effective_epoch = (
            self.current_epoch // self.decay_every
        ) * self.decay_every

        t = effective_epoch / float(self.total_decay_epochs)
        return _clamp(t)

    def _get_current_max_blur_radius(self) -> float:
        t = self._get_progress()

        if self.schedule == "linear":
            factor = 1.0 - t
        elif self.schedule == "cosine":
            factor = 0.5 * (1.0 + math.cos(math.pi * t))
        else:
            raise ValueError(f"Unknown schedule: {self.schedule}")

        return (
            self.final_max_blur_radius
            + (self.initial_max_blur_radius - self.final_max_blur_radius) * factor
        )

    def _blur(self, image: Image.Image, radius: float) -> Image.Image:
        if radius <= 0.0:
            return image.copy()

        if self.blur_mode == "box":
            return image.filter(ImageFilter.BoxBlur(radius))

        if self.blur_mode == "gaussian":
            return image.filter(ImageFilter.GaussianBlur(radius))

        raise ValueError(f"Unknown blur_mode: {self.blur_mode}")

    def _build_blur_stack(
        self,
        image: Image.Image,
        current_max_blur_radius: float,
    ) -> np.ndarray:
        radii = []
        blurred_arrays = []

        for i in range(self.blur_levels):
            t = i / float(self.blur_levels - 1)
            radius = current_max_blur_radius * t
            radius_key = round(radius, 3)

            if len(radii) > 0 and abs(radius_key - radii[-1]) < 1e-6:
                blurred_arrays.append(blurred_arrays[-1])
                continue

            blurred = self._blur(image, radius)
            arr = np.asarray(blurred).astype(np.float32)

            radii.append(radius_key)
            blurred_arrays.append(arr)

        return np.stack(blurred_arrays, axis=0)

    def _compute_distance_map(
        self,
        W: int,
        H: int,
        labels: Annotation,
    ) -> np.ndarray:
        xs = np.arange(W, dtype=np.float32)[None, :]
        ys = np.arange(H, dtype=np.float32)[:, None]

        min_dist_sq = np.full((H, W), np.inf, dtype=np.float32)

        for x, y in _annotation_reference_points(labels):
            jitter_x = random.uniform(-self.center_jitter, self.center_jitter)
            jitter_y = random.uniform(-self.center_jitter, self.center_jitter)

            x = _clamp(x + jitter_x)
            y = _clamp(y + jitter_y)

            px = x * (W - 1)
            py = y * (H - 1)

            dist_sq = (xs - px) ** 2 + (ys - py) ** 2
            min_dist_sq = np.minimum(min_dist_sq, dist_sq)

        return np.sqrt(min_dist_sq)

    def _compute_blend_position_map(
        self,
        distance_map: np.ndarray,
        W: int,
        H: int,
    ) -> np.ndarray:
        base = float(min(W, H))

        keep_px = self.keep_radius * base
        fade_px = self.fade_radius * base

        if fade_px <= keep_px:
            fade_px = keep_px + 1.0

        t = (distance_map - keep_px) / (fade_px - keep_px)
        t = np.clip(t, 0.0, 1.0)

        if self.smoothstep:
            t = t * t * (3.0 - 2.0 * t)

        return t * float(self.blur_levels - 1)

    def __call__(
        self,
        image: Image.Image,
        labels: Annotation,
    ) -> tuple[Image.Image, Annotation]:
        new_labels = _clone_annotation(labels)

        if random.random() > self.p:
            return image, new_labels

        if len(new_labels.cloth.pairs) == 0:
            return image, new_labels

        W, H = image.size
        current_max_blur_radius = self._get_current_max_blur_radius()

        if current_max_blur_radius <= 0.0:
            return image, new_labels

        blur_stack = self._build_blur_stack(image, current_max_blur_radius)
        distance_map = self._compute_distance_map(W, H, new_labels)
        level_map = self._compute_blend_position_map(distance_map, W, H)

        level0 = np.floor(level_map).astype(np.int32)
        level1 = np.clip(level0 + 1, 0, self.blur_levels - 1)
        alpha = (level_map - level0).astype(np.float32)

        yy, xx = np.indices((H, W))

        if blur_stack.ndim == 4:
            pix0 = blur_stack[level0, yy, xx]
            pix1 = blur_stack[level1, yy, xx]

            out = (
                pix0 * (1.0 - alpha[..., None])
                + pix1 * alpha[..., None]
            )
        else:
            pix0 = blur_stack[level0, yy, xx]
            pix1 = blur_stack[level1, yy, xx]

            out = pix0 * (1.0 - alpha) + pix1 * alpha

        out = np.clip(out, 0, 255).astype(np.uint8)
        return Image.fromarray(out), new_labels


