class RandomHorizontalFlip(Transform):
    def __init__(self, p: float = 0.5):
        super().__init__()
        self.p = p

    def __call__(
        self,
        image: Image.Image,
        labels: Annotation,
    ) -> tuple[Image.Image, Annotation]:
        if random.random() >= self.p:
            return image, _clone_annotation(labels)

        flipped = image.transpose(_FLIP_LEFT_RIGHT)

        def transform_bbox(bbox):
            x1, y1, x2, y2 = _bbox_to_xyxy(bbox)
            return 1.0 - x2, y1, 1.0 - x1, y2

        new_labels = _transform_annotation_boxes(labels, transform_bbox)
        return flipped, new_labels


class RandomHorizontalTranslation(Transform):
    def __init__(
        self,
        p: float = 0.5,
        min: float = -0.3,
        max: float = 0.3,
        fill=(0, 0, 0),
    ):
        super().__init__()
        self.p = p
        self.min = min
        self.max = max
        self.fill = fill

    def __call__(
        self,
        image: Image.Image,
        labels: Annotation,
    ) -> tuple[Image.Image, Annotation]:
        if random.random() >= self.p:
            return image, _clone_annotation(labels)

        W, H = image.size
        shift = random.uniform(self.min, self.max)
        pixel_shift = int(round(shift * W))

        translated = Image.new(
            image.mode,
            (W, H),
            _coerce_fill(image, self.fill),
        )
        translated.paste(image, (pixel_shift, 0))

        def transform_bbox(bbox):
            x1, y1, x2, y2 = _bbox_to_xyxy(bbox)
            return x1 + shift, y1, x2 + shift, y2

        new_labels = _transform_annotation_boxes(labels, transform_bbox)
        return translated, new_labels


class RandomVerticalTranslation(Transform):
    def __init__(
        self,
        p: float = 0.5,
        min: float = -0.3,
        max: float = 0.3,
        fill=(0, 0, 0),
    ):
        super().__init__()
        self.p = p
        self.min = min
        self.max = max
        self.fill = fill

    def __call__(
        self,
        image: Image.Image,
        labels: Annotation,
    ) -> tuple[Image.Image, Annotation]:
        if random.random() >= self.p:
            return image, _clone_annotation(labels)

        W, H = image.size
        shift = random.uniform(self.min, self.max)
        pixel_shift = int(round(shift * H))

        translated = Image.new(
            image.mode,
            (W, H),
            _coerce_fill(image, self.fill),
        )
        translated.paste(image, (0, pixel_shift))

        def transform_bbox(bbox):
            x1, y1, x2, y2 = _bbox_to_xyxy(bbox)
            return x1, y1 + shift, x2, y2 + shift

        new_labels = _transform_annotation_boxes(labels, transform_bbox)
        return translated, new_labels


class RandomRotation(Transform):
    def __init__(
        self,
        p: float = 0.5,
        min_angle: float = -90.0,
        max_angle: float = 90.0,
        fill=(0, 0, 0),
    ):
        super().__init__()
        self.p = p
        self.min_angle = min_angle
        self.max_angle = max_angle
        self.fill = fill

    def __call__(
        self,
        image: Image.Image,
        labels: Annotation,
    ) -> tuple[Image.Image, Annotation]:
        if random.random() >= self.p:
            return image, _clone_annotation(labels)

        W, H = image.size
        angle = random.uniform(self.min_angle, self.max_angle)

        rotated = image.rotate(
            angle,
            resample=_BILINEAR,
            expand=False,
            fillcolor=_coerce_fill(image, self.fill),
        )

        cx = W / 2.0
        cy = H / 2.0

        # Keep the same sign convention as the original implementation.
        theta = -angle * math.pi / 180.0
        cos_t = math.cos(theta)
        sin_t = math.sin(theta)

        def rotate_point(px: float, py: float) -> tuple[float, float]:
            dx = px - cx
            dy = py - cy

            new_dx = dx * cos_t - dy * sin_t
            new_dy = dx * sin_t + dy * cos_t

            return cx + new_dx, cy + new_dy

        def transform_bbox(bbox):
            x1, y1, x2, y2 = _bbox_to_xyxy(bbox)

            corners = [
                (x1 * W, y1 * H),
                (x2 * W, y1 * H),
                (x2 * W, y2 * H),
                (x1 * W, y2 * H),
            ]

            rotated_corners = [rotate_point(px, py) for px, py in corners]

            xs = [point[0] / W for point in rotated_corners]
            ys = [point[1] / H for point in rotated_corners]

            return min(xs), min(ys), max(xs), max(ys)

        new_labels = _transform_annotation_boxes(labels, transform_bbox)
        return rotated, new_labels


class RandomSafeCrop(Transform):
    def __init__(
        self,
        p: float = 0.4,
        min_width: float = 0.7,
        max_width: float = 1.0,
        min_height: float = 0.7,
        max_height: float = 1.0,
    ):
        super().__init__()
        self.p = p
        self.min_width = min_width
        self.max_width = max_width
        self.min_height = min_height
        self.max_height = max_height

    def __call__(
        self,
        image: Image.Image,
        labels: Annotation,
    ) -> tuple[Image.Image, Annotation]:
        if random.random() >= self.p:
            return image, _clone_annotation(labels)

        W, H = image.size

        crop_w = int(random.uniform(self.min_width, self.max_width) * W)
        crop_h = int(random.uniform(self.min_height, self.max_height) * H)

        crop_w = max(1, min(crop_w, W))
        crop_h = max(1, min(crop_h, H))

        if crop_w == W and crop_h == H:
            return image, _clone_annotation(labels)

        left = random.randint(0, W - crop_w)
        top = random.randint(0, H - crop_h)
        right = left + crop_w
        bottom = top + crop_h

        cropped = image.crop((left, top, right, bottom))

        def transform_bbox(bbox):
            x1, y1, x2, y2 = _bbox_to_xyxy(bbox)

            return (
                (x1 * W - left) / crop_w,
                (y1 * H - top) / crop_h,
                (x2 * W - left) / crop_w,
                (y2 * H - top) / crop_h,
            )

        new_labels = _transform_annotation_boxes(labels, transform_bbox)
        return cropped, new_labels


class RandomZoomOut(Transform):
    def __init__(
        self,
        p: float = 0.5,
        min_scale: float = 0.7,
        max_scale: float = 1.0,
    ):
        super().__init__()
        self.p = p
        self.min_scale = min_scale
        self.max_scale = max_scale

    def __call__(
        self,
        image: Image.Image,
        labels: Annotation,
    ) -> tuple[Image.Image, Annotation]:
        if random.random() >= self.p:
            return image, _clone_annotation(labels)

        W, H = image.size

        scale = random.uniform(self.min_scale, self.max_scale)

        new_W = max(1, int(scale * W))
        new_H = max(1, int(scale * H))

        if new_W == W and new_H == H:
            return image, _clone_annotation(labels)

        fill_value = random.randint(0, 80)
        fill = _coerce_fill(image, fill_value)

        resized = image.resize((new_W, new_H), _BILINEAR)

        canvas = Image.new(image.mode, (W, H), fill)

        offset_x = random.randint(0, W - new_W)
        offset_y = random.randint(0, H - new_H)

        canvas.paste(resized, (offset_x, offset_y))

        scale_x = new_W / float(W)
        scale_y = new_H / float(H)
        offset_x_norm = offset_x / float(W)
        offset_y_norm = offset_y / float(H)

        def transform_bbox(bbox):
            x1, y1, x2, y2 = _bbox_to_xyxy(bbox)

            return (
                x1 * scale_x + offset_x_norm,
                y1 * scale_y + offset_y_norm,
                x2 * scale_x + offset_x_norm,
                y2 * scale_y + offset_y_norm,
            )

        new_labels = _transform_annotation_boxes(labels, transform_bbox)
        return canvas, new_labels


class RandomResize(Transform):
    def __init__(self, sizes, resample=_BILINEAR):
        super().__init__()
        self.sizes = list(sizes)
        self.resample = resample

    def __call__(
        self,
        image: Image.Image,
        labels: Annotation,
    ) -> tuple[Image.Image, Annotation]:
        size = random.choice(self.sizes)
        resized = image.resize((size, size), self.resample)

        # Labels stay unchanged because bboxes are normalized.
        return resized, _clone_annotation(labels)


# ---------------------------------------------------------------------------
# Debug transform
# ---------------------------------------------------------------------------

class SaveImage(Transform):
    """
    Debug transform.

    Saves a copy of the image with button and fastener centers/bboxes drawn.
    Does not modify the returned image or labels.
    """
    def __init__(self, directory: str = "tests", radius: int = 4):
        super().__init__()
        self.directory = directory
        self.radius = radius

    def __call__(
        self,
        image: Image.Image,
        labels: Annotation,
    ) -> tuple[Image.Image, Annotation]:
        new_labels = _clone_annotation(labels)

        os.makedirs(self.directory, exist_ok=True)

        out = image.copy()
        draw = ImageDraw.Draw(out)
        W, H = out.size

        for i, pair in enumerate(new_labels.cloth.pairs):
            button_bbox = pair.button.bbox
            fastener_bbox = pair.fastener.bbox

            self._draw_bbox(
                draw,
                button_bbox,
                W,
                H,
                outline=(255, 0, 0),
                text=f"B{i}",
            )

            self._draw_bbox(
                draw,
                fastener_bbox,
                W,
                H,
                outline=(0, 255, 0),
                text=f"F{i}",
            )

        filename = f"{random.randrange(500_000)}.png"
        out.save(os.path.join(self.directory, filename))

        return image, new_labels

    def _draw_bbox(
        self,
        draw: ImageDraw.ImageDraw,
        bbox,
        W: int,
        H: int,
        outline,
        text: str,
    ) -> None:
        cx = bbox.cx * W
        cy = bbox.cy * H

        x1 = (bbox.cx - bbox.w / 2.0) * W
        y1 = (bbox.cy - bbox.h / 2.0) * H
        x2 = (bbox.cx + bbox.w / 2.0) * W
        y2 = (bbox.cy + bbox.h / 2.0) * H

        radius = self.radius

        draw.rectangle(
            [x1, y1, x2, y2],
            outline=outline,
            width=2,
        )

        draw.ellipse(
            [cx - radius, cy - radius, cx + radius, cy + radius],
            fill=outline,
            outline=(255, 255, 255),
        )

        draw.text(
            (cx + 6, cy - 6),
            text,
            fill=outline,
        )



class RandomFastenerPartMasking(Transform):
    """
    Randomly masks image regions containing at least one fastener.

    Main purpose:
    - hide a fastener / velcro region while keeping the pair annotation
      whenever the corresponding button remains visible.
    - this forces the model to infer the full button-fastener pair from the
      visible button and surrounding context.

    Annotation rule:
    - The input Annotation is never modified in place.
    - If a button is covered by the mask, the whole pair is removed.
    - If a fastener is covered but its button is not covered, the pair is kept
      and the fastener bbox is kept unchanged. This is intentional: the target
      remains supervised even though the visual evidence is occluded.
    - The `visible` field is not used for decisions.
    """

    def __init__(
        self,
        p: float = 0.3,
        target_fastener_types: tuple[str, ...] | None = ("velcro",),
        min_width: float = 0.08,
        max_width: float = 0.35,
        min_height: float = 0.08,
        max_height: float = 0.35,
        max_masks: int = 1,
        button_remove_mode: str = "center",  # "center" or "overlap"
        min_button_overlap: float = 0.75,
        fill_mode: str = "random_gray",     # "random_gray" or "constant"
        fill=(0, 0, 0),
        max_trials: int = 20,
    ):
        super().__init__()

        self.p = p
        self.target_fastener_types = target_fastener_types

        self.min_width = min_width
        self.max_width = max_width
        self.min_height = min_height
        self.max_height = max_height

        self.max_masks = max(1, int(max_masks))

        self.button_remove_mode = button_remove_mode
        self.min_button_overlap = min_button_overlap

        self.fill_mode = fill_mode
        self.fill = fill

        self.max_trials = max(1, int(max_trials))

        if self.min_width <= 0.0 or self.max_width <= 0.0:
            raise ValueError("min_width and max_width must be positive")
        if self.min_height <= 0.0 or self.max_height <= 0.0:
            raise ValueError("min_height and max_height must be positive")
        if self.min_width > self.max_width:
            raise ValueError("min_width must be <= max_width")
        if self.min_height > self.max_height:
            raise ValueError("min_height must be <= max_height")
        if button_remove_mode not in {"center", "overlap"}:
            raise ValueError("button_remove_mode must be 'center' or 'overlap'")
        if fill_mode not in {"random_gray", "constant"}:
            raise ValueError("fill_mode must be 'random_gray' or 'constant'")

    def _is_target_fastener(self, pair) -> bool:
        return True

    def _make_fill(self, image: Image.Image):
        if self.fill_mode == "constant":
            return _coerce_fill(image, self.fill)

        value = random.randint(0, 160)
        return _coerce_fill(image, value)

    def _bbox_to_pixel_xyxy(
        self,
        bbox,
        W: int,
        H: int,
    ) -> tuple[float, float, float, float]:
        x1, y1, x2, y2 = _bbox_to_xyxy(bbox)
        return x1 * W, y1 * H, x2 * W, y2 * H

    def _rect_area(
        self,
        rect: tuple[float, float, float, float],
    ) -> float:
        x1, y1, x2, y2 = rect

        if x1 > x2:
            x1, x2 = x2, x1
        if y1 > y2:
            y1, y2 = y2, y1

        return max(0.0, x2 - x1) * max(0.0, y2 - y1)

    def _intersection_area(
        self,
        a: tuple[float, float, float, float],
        b: tuple[float, float, float, float],
    ) -> float:
        ax1, ay1, ax2, ay2 = a
        bx1, by1, bx2, by2 = b

        if ax1 > ax2:
            ax1, ax2 = ax2, ax1
        if ay1 > ay2:
            ay1, ay2 = ay2, ay1
        if bx1 > bx2:
            bx1, bx2 = bx2, bx1
        if by1 > by2:
            by1, by2 = by2, by1

        ix1 = max(ax1, bx1)
        iy1 = max(ay1, by1)
        ix2 = min(ax2, bx2)
        iy2 = min(ay2, by2)

        return max(0.0, ix2 - ix1) * max(0.0, iy2 - iy1)

    def _button_is_made_invisible(
        self,
        button_bbox,
        mask_rect: tuple[float, float, float, float],
        W: int,
        H: int,
    ) -> bool:
        """
        Decide whether a masked region makes a button unusable.

        "center" mode matches the earlier RandomButtonErasing behavior:
        if the button center is inside the erased region, remove the pair.

        "overlap" mode removes the pair only if a sufficiently large fraction
        of the button bbox is masked.
        """
        if self.button_remove_mode == "center":
            point = (
                button_bbox.cx * W,
                button_bbox.cy * H,
            )
            return _rect_contains_point(point, mask_rect)

        button_rect = self._bbox_to_pixel_xyxy(button_bbox, W, H)
        button_area = self._rect_area(button_rect)

        if button_area <= 0.0:
            return False

        overlap = self._intersection_area(button_rect, mask_rect)
        overlap_fraction = overlap / button_area

        return overlap_fraction >= self.min_button_overlap

    def _sample_mask_around_fastener(
        self,
        fastener_bbox,
        W: int,
        H: int,
    ) -> tuple[int, int, int, int]:
        """
        Build a random mask rectangle guaranteed to contain the selected
        fastener center.
        """
        fx = fastener_bbox.cx * W
        fy = fastener_bbox.cy * H

        mask_w = random.uniform(self.min_width, self.max_width) * W
        mask_h = random.uniform(self.min_height, self.max_height) * H

        mask_w = max(1, min(int(round(mask_w)), W))
        mask_h = max(1, min(int(round(mask_h)), H))

        # Randomize the fastener position inside the mask, while ensuring the
        # mask still contains the fastener center.
        local_x = random.uniform(0.2, 0.8) * mask_w
        local_y = random.uniform(0.2, 0.8) * mask_h

        x1 = int(round(fx - local_x))
        y1 = int(round(fy - local_y))

        x1 = max(0, min(x1, W - mask_w))
        y1 = max(0, min(y1, H - mask_h))

        x2 = x1 + mask_w
        y2 = y1 + mask_h

        return x1, y1, x2, y2

    def __call__(
        self,
        image: Image.Image,
        labels: Annotation,
    ) -> tuple[Image.Image, Annotation]:
        new_labels = _clone_annotation(labels)

        if random.random() > self.p:
            return image, new_labels

        candidate_pairs = [
            pair
            for pair in new_labels.cloth.pairs
            if self._is_target_fastener(pair)
        ]

        if len(candidate_pairs) == 0:
            return image, new_labels

        W, H = image.size
        out = image.copy()
        draw = ImageDraw.Draw(out)

        n_masks = random.randint(1, self.max_masks)
        mask_rects: list[tuple[int, int, int, int]] = []

        for _ in range(n_masks):
            selected_pair = random.choice(candidate_pairs)

            for _trial in range(self.max_trials):
                mask_rect = self._sample_mask_around_fastener(
                    selected_pair.fastener.bbox,
                    W,
                    H,
                )

                # This is normally guaranteed by construction, but keep the
                # check explicit because the image boundary clamp can move the
                # mask.
                fastener_center = (
                    selected_pair.fastener.bbox.cx * W,
                    selected_pair.fastener.bbox.cy * H,
                )

                if _rect_contains_point(fastener_center, mask_rect):
                    mask_rects.append(mask_rect)
                    draw.rectangle(mask_rect, fill=self._make_fill(image))
                    break

        if len(mask_rects) == 0:
            return image, new_labels

        kept_pairs = []

        for pair in new_labels.cloth.pairs:
            button_removed = any(
                self._button_is_made_invisible(
                    pair.button.bbox,
                    mask_rect,
                    W,
                    H,
                )
                for mask_rect in mask_rects
            )

            if button_removed:
                # If the button is made invisible, remove the whole pair.
                continue

            # If the fastener is masked but the button remains visible, keep
            # the pair unchanged. This is exactly the occlusion-learning case.
            kept_pairs.append(pair)

        new_labels.cloth.pairs = kept_pairs

        return out, new_labels
    

class RandomQuarterTurn(Transform):
    """
    Randomly rotate the image by either +90° or -90°.

    Pillow's ROTATE_90 corresponds to a 90° counter-clockwise rotation.
    ROTATE_270 corresponds to a 90° clockwise rotation.

    The output dimensions are swapped:
        (W, H) -> (H, W)

    Bounding boxes remain normalized in cx, cy, w, h format.
    """

    def __init__(self, p: float = 0.5):
        super().__init__()
        self.p = p

    def __call__(
        self,
        image: Image.Image,
        labels: Annotation,
    ) -> tuple[Image.Image, Annotation]:
        if random.random() >= self.p:
            return image, _clone_annotation(labels)

        rotate_counter_clockwise = random.choice((True, False))

        if rotate_counter_clockwise:
            rotated = image.transpose(_ROTATE_90)

            def transform_bbox(bbox):
                """
                For a +90° counter-clockwise rotation:

                    x' = y
                    y' = 1 - x
                """
                x1, y1, x2, y2 = _bbox_to_xyxy(bbox)

                return (
                    y1,
                    1.0 - x2,
                    y2,
                    1.0 - x1,
                )

        else:
            rotated = image.transpose(_ROTATE_270)

            def transform_bbox(bbox):
                """
                For a -90° clockwise rotation:

                    x' = 1 - y
                    y' = x
                """
                x1, y1, x2, y2 = _bbox_to_xyxy(bbox)

                return (
                    1.0 - y2,
                    x1,
                    1.0 - y1,
                    x2,
                )

        new_labels = _transform_annotation_boxes(labels, transform_bbox)
        return rotated, new_labels